<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {request} from '@/utils/request';
import {usePermissions} from '@/store/modules/permission.store';
const props=defineProps<{modelValue:boolean;form:any;saving:boolean}>();
const emit=defineEmits(['update:modelValue','save']);
const permissions=usePermissions(),environment=ref(false),advanced=ref(false),members=ref<any[]>([]);
const kernels=ref<any[]>([]),kernelError=ref('');
watch([()=>props.modelValue,()=>kernels.value],()=>{
  if(!props.modelValue||props.form.id||kernels.value.some(k=>k.version===props.form.kernelVersion&&!k.disabled))return;
  const selected=kernels.value.find(k=>k.recommended&&!k.disabled)||kernels.value.find(k=>!k.disabled);
  if(selected){props.form.kernelVersion=selected.version;newUa();}
});
const platforms=['TikTok Shop','亚马逊','Shopee','Lazada','Temu','SHEIN','eBay','沃尔玛','速卖通','Shopify','美客多','Coupang','Allegro','抖店','拼多多','淘宝','快手小店','微信小店','其他平台'];
onMounted(async()=>{
  const loadKernels=async()=>{try{const result=await request('/runtime/kernels');const list=result.kernels||result.contents?.win||[];kernels.value=list.filter((k:any)=>(!k.platform||k.platform==='win32')&&(!k.arch||k.arch==='x64')).map((k:any)=>({...k,version:String(k.version),disabled:!!(k.disabled||k.disableWin),recommended:!!(k.recommended||k.isRecommend)}));if(!kernels.value.length)kernelError.value='暂无已发布的内核版本';}catch{kernelError.value='无法获取内核清单，请检查内核资源服务';}};
  await Promise.all([loadKernels(),permissions.can('shop.grant')?request('/members').then(value=>{members.value=value.filter((m:any)=>m.enabled);}):Promise.resolve()]);
});
const ruleMode=computed({get:()=>props.form.fingerprint.accessRules?.mode||'blacklist',set:mode=>{props.form.fingerprint.accessRules={...(props.form.fingerprint.accessRules||{domains:[]}),mode};}});
const ruleDomains=computed({get:()=>(props.form.fingerprint.accessRules?.domains||[]).join('\n'),set:(value:string)=>{props.form.fingerprint.accessRules={mode:ruleMode.value,...props.form.fingerprint.accessRules,domains:value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean)};}});
function reset(){Object.assign(props.form.fingerprint,{language:'zh-CN',timezone:'Asia/Shanghai',webRtc:'disabled',speechVoices:'privacy',fonts:'privacy',canvas:'privacy',audio:'privacy',clientRects:'privacy',fontMetrics:'privacy',webglFingerprint:'privacy'});}
function syncNoise(key:string){if(['canvas','fontMetrics','webglFingerprint'].includes(key))for(const field of ['canvas','fontMetrics','webglFingerprint'])props.form.fingerprint[field]=props.form.fingerprint[key];}
function newUa(){const os=props.form.fingerprint.os==='Mac'?'Macintosh; Intel Mac OS X 10_15_7':props.form.fingerprint.os==='Android'?'Linux; Android 13':'Windows NT 10.0; Win64; x64';props.form.fingerprint.userAgent=`Mozilla/5.0 (${os}) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/${props.form.kernelVersion.includes(".")?props.form.kernelVersion:props.form.kernelVersion+".0.0.0"} Safari/537.36`;}
</script>
<template><el-dialog :model-value="modelValue" :title="form.id?'编辑店铺':'新建店铺'" width="860px" top="5vh" :close-on-click-modal="false" @update:model-value="emit('update:modelValue',$event)"><el-form label-width="160px" class="mall-editor" v-if="form.fingerprint">
  <el-form-item label="所属平台" required><el-select v-model="form.platform" filterable allow-create default-first-option placeholder="请选择添加的平台站点"><el-option v-for="p in platforms" :key="p" :value="p"/></el-select></el-form-item>
  <el-form-item label="平台站点 / 地址" required><el-input v-model="form.startUrl" placeholder="请输入平台站点的 HTTPS 地址"/></el-form-item>
  <el-form-item label="店铺名称" required><el-input v-model="form.name" maxlength="100" show-word-limit placeholder="用于展示、区分不同账号，可自定义名称"/></el-form-item>
  <el-form-item label="店铺账号"><el-input v-model="form.accountName" placeholder="请输入平台登录账号"/></el-form-item>
  <el-form-item label="店铺密码"><el-input v-model="form.accountPassword" type="password" show-password :placeholder="form.id?'不修改请留空；密码不会返回页面':'请输入平台登录密码'"/><el-checkbox v-model="form.fingerprint.accountLock">锁定输入框</el-checkbox></el-form-item>
  <el-form-item label="店铺备注"><el-input v-model="form.remark" maxlength="50" show-word-limit placeholder="请输入店铺备注"/></el-form-item>
  <el-form-item v-if="permissions.can('shop.grant')&&!form.id" label="授权成员"><el-select v-model="form.granteeIds" multiple filterable placeholder="请选择授权人员"><el-option v-for="m in members" :key="m.id" :value="m.id" :label="`${m.displayName} (${m.username})`"/></el-select></el-form-item>
  <el-form-item label="Passkey 配置"><el-checkbox v-model="form.fingerprint.autoInjectPasskey" :disabled="form.fingerprint.disabledPasskey">自动注入 Passkey</el-checkbox><el-tooltip content="开启后使用系统认证器，停止助手的虚拟认证器注入"><el-checkbox v-model="form.fingerprint.disabledPasskey">使用本地 Passkey</el-checkbox></el-tooltip></el-form-item>
  <el-form-item label="谷歌浏览器默认记住密码"><el-radio-group v-model="form.fingerprint.rememberPassword"><el-radio :value="true">开启</el-radio><el-radio :value="false">关闭</el-radio></el-radio-group></el-form-item>
  <el-form-item label="店铺共同访问限制"><el-radio-group :model-value="'unlimited'"><el-radio value="unlimited">不限</el-radio><el-tooltip content="跨客户端占用控制尚未接通"><el-radio value="single" disabled>限定 1 人</el-radio></el-tooltip></el-radio-group></el-form-item>
  <el-form-item label="消息提示"><el-radio-group v-model="form.fingerprint.notifications"><el-radio :value="true">开启</el-radio><el-radio :value="false">关闭</el-radio></el-radio-group></el-form-item>
  <el-divider/><el-form-item label="浏览器环境配置"><el-button link type="primary" @click="environment=!environment">{{environment?'收起配置':'展开配置'}}</el-button></el-form-item>
  <template v-if="environment"><div class="fingerprint-note">配置在下次打开店铺时生效。同一店铺保留固定的环境标识。当前内核的 Canvas、字体测量与 WebGL 噪声会同步切换。WebRTC 禁用和语音列表隐藏由助手限制网页接口。</div>
  <el-form-item label="语言"><el-radio-group v-model="form.fingerprint.languageMode"><el-radio value="ip" disabled>跟随 IP</el-radio><el-radio value="custom">自定义</el-radio></el-radio-group><el-select v-model="form.fingerprint.language" style="width:180px;margin-left:16px"><el-option label="简体中文" value="zh-CN"/><el-option label="English" value="en-US"/><el-option label="日本語" value="ja-JP"/></el-select></el-form-item>
  <el-form-item label="WebGL"><el-radio-group v-model="form.fingerprint.webgl"><el-radio :value="true">开启</el-radio><el-radio :value="false">关闭</el-radio></el-radio-group></el-form-item>
  <el-form-item label="默认浏览器"><el-radio-group :model-value="'Chrome'"><el-radio value="Chrome">Chrome</el-radio><el-radio value="Firefox" disabled>Firefox</el-radio></el-radio-group></el-form-item>
  <el-form-item label="内核版本" required><el-select v-model="form.kernelVersion" filterable @change="newUa"><el-option v-if="form.kernelVersion&&!kernels.some(k=>k.version===form.kernelVersion)" :value="form.kernelVersion" :label="form.kernelVersion+'（未发布）'" disabled/><el-option v-for="kernel in kernels" :key="kernel.version" :value="kernel.version" :label="kernel.version+(kernel.recommended?'（推荐）':'')" :disabled="kernel.disabled"/></el-select><span v-if="kernelError" class="muted">{{kernelError}}</span></el-form-item>
  <el-form-item label="User Agent"><el-input v-model="form.fingerprint.userAgent" type="textarea" :rows="2"/><el-button link type="primary" @click="newUa">按所选系统和内核生成 UA</el-button></el-form-item>
  <el-form-item label="UA 版本"><el-input :model-value="form.kernelVersion" readonly/></el-form-item>
  <el-form-item label="窗口尺寸"><el-select v-model="form.fingerprint.resolution"><el-option v-for="s in ['1920x1080','1536x864','1440x900','1366x768','2560x1440']" :key="s" :value="s"/></el-select><el-tooltip content="设置浏览器窗口大小；网页读取的屏幕尺寸仍由当前内核和显示器决定"><span class="muted" style="margin-left:12px">窗口大小说明</span></el-tooltip></el-form-item>
  <el-form-item label="操作系统"><el-radio-group v-model="form.fingerprint.os" @change="newUa"><el-radio value="Windows">Windows</el-radio><el-radio value="Mac">MAC OS</el-radio><el-radio value="Android" disabled>Android</el-radio></el-radio-group></el-form-item>
  <el-form-item label="高级设置"><el-button link type="primary" @click="advanced=!advanced">{{advanced?'收起':'展开'}}</el-button><el-button v-if="advanced" link @click="reset">恢复默认设置</el-button></el-form-item>
  <template v-if="advanced"><el-form-item label="WebRTC"><el-radio-group v-model="form.fingerprint.webRtc"><el-radio value="privacy">隐私</el-radio><el-radio value="replace" disabled>替换</el-radio><el-radio value="real">真实</el-radio><el-radio value="disabled">禁用</el-radio></el-radio-group></el-form-item><el-form-item label="SpeechVoices"><el-radio-group v-model="form.fingerprint.speechVoices"><el-radio value="privacy">隐私</el-radio><el-radio value="real">真实</el-radio></el-radio-group></el-form-item><el-form-item label="时区"><el-radio-group :model-value="'custom'"><el-radio value="ip" disabled>匹配 IP</el-radio><el-radio value="custom">自定义</el-radio></el-radio-group><el-input v-model="form.fingerprint.timezone" style="width:220px;margin-left:16px"/></el-form-item><el-form-item label="字体"><el-radio-group v-model="form.fingerprint.fonts"><el-radio value="privacy">隐私</el-radio><el-radio value="real">真实</el-radio></el-radio-group></el-form-item></template>
  <template v-if="advanced"><el-form-item v-for="item in [{key:'canvas',label:'Canvas'},{key:'audio',label:'Audio'},{key:'clientRects',label:'Client Rects'},{key:'fontMetrics',label:'字体测量'},{key:'webglFingerprint',label:'WebGL 指纹'}]" :key="item.key" :label="item.label"><el-radio-group v-model="form.fingerprint[item.key]" @change="syncNoise(item.key)"><el-radio value="privacy">隐私</el-radio><el-radio value="real">真实</el-radio></el-radio-group></el-form-item><el-form-item label="硬件加速"><el-switch v-model="form.fingerprint.hardwareAcceleration"/></el-form-item><el-form-item label="访问范围"><el-radio-group v-model="ruleMode"><el-radio value="blacklist">禁止指定网站</el-radio><el-radio value="whitelist">仅允许指定网站</el-radio></el-radio-group></el-form-item><el-form-item label="网站域名"><el-input v-model="ruleDomains" type="textarea" :rows="3" placeholder="每行一个域名，例如 example.com；留空不限制"/><span class="muted">设备检测与本地控制页面不受允许列表限制。</span></el-form-item></template>
  </template>
</el-form><template #footer><el-button v-if="permissions.can('device.view')&&permissions.can('shop.edit')" type="primary" :loading="saving" @click="emit('save',true)">保存并绑定设备</el-button><el-button @click="emit('update:modelValue',false)">取消</el-button><el-button :loading="saving" @click="emit('save',false)">保存</el-button></template></el-dialog></template>
